import {
  HELP_OPTIONS,
  REQUIRED_LONG_OPTIONS,
  REQUIRED_OPTION_SET,
} from './option-spec.mjs';

function createSeenMap() {
  return new Map(REQUIRED_LONG_OPTIONS.map((option) => [option, []]));
}

function recordSeen(seen, option, value, source) {
  if (!REQUIRED_OPTION_SET.has(option)) {
    return;
  }

  seen.get(option).push({ value, source });
}

export function inspectArgv(argv) {
  const rawArgs = [...argv];
  const seen = createSeenMap();
  const events = [];
  let awaitingValueFor = null;
  let endOfOptions = false;

  for (const token of rawArgs) {
    if (awaitingValueFor !== null) {
      recordSeen(seen, awaitingValueFor, token, 'separate');
      events.push({
        kind: 'option',
        option: awaitingValueFor,
        value: token,
        source: 'separate',
      });
      awaitingValueFor = null;
      continue;
    }

    if (!endOfOptions && token === '--') {
      endOfOptions = true;
      events.push({ kind: 'end_of_options' });
      continue;
    }

    if (!endOfOptions && HELP_OPTIONS.has(token)) {
      events.push({ kind: 'help', option: token });
      continue;
    }

    if (!endOfOptions && token.startsWith('--')) {
      const equalsIndex = token.indexOf('=');

      if (equalsIndex !== -1) {
        const option = token.slice(0, equalsIndex);
        const value = token.slice(equalsIndex + 1);
        recordSeen(seen, option, value, 'attached');
        events.push({ kind: 'option', option, value, source: 'attached' });
        continue;
      }

      awaitingValueFor = token;
      continue;
    }

    events.push({ kind: 'other', value: token });
  }

  if (awaitingValueFor !== null) {
    events.push({ kind: 'missing_value', option: awaitingValueFor });
  }

  return {
    rawArgs,
    events,
    seen,
  };
}

