import { spawnSync } from 'node:child_process';
import { resolveReferenceExecutablePath } from './reference-path.mjs';

export function runReferenceExecutable(parsedArgv) {
  const executablePath = resolveReferenceExecutablePath();

  const child = spawnSync(executablePath, parsedArgv.rawArgs, {
    stdio: 'inherit',
  });

  if (child.error) {
    throw child.error;
  }

  if (child.signal) {
    process.kill(process.pid, child.signal);
    return;
  }

  process.exitCode = child.status ?? 1;
}

